<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Criar conta | ImoveCheck</title><link rel="stylesheet" href="assets/css/auth.css"><script src="assets/js/auth.js" defer></script></head><body data-auth-page="register">
<header class="topbar"><div class="topbar-inner"><a class="brand" href="login.php"><span class="brand-icon">▤</span><strong>ImoveCheck</strong></a><span class="brand-divider"></span><span class="brand-subtitle">Sistema de Inspeção de Imóveis</span></div></header>
<main class="auth-main"><section class="auth-card"><h1>Crie sua conta</h1><p class="subtitle">Cadastre-se para acessar o ImoveCheck.</p><form id="register-form" novalidate>
<label for="nome">Nome completo</label><div class="input-wrap"><span>♙</span><input id="nome" name="nome" type="text" autocomplete="name" placeholder="Seu nome" maxlength="100" required></div>
<label for="email">E-mail</label><div class="input-wrap"><span>✉</span><input id="email" name="email" type="email" autocomplete="email" placeholder="seu@email.com" maxlength="190" required></div>
<label for="senha">Senha</label><div class="input-wrap"><span>♙</span><input id="senha" name="senha" type="password" autocomplete="new-password" placeholder="Mínimo de 8 caracteres" required minlength="8"><button class="toggle-password" type="button" data-toggle="senha">◎</button></div>
<label for="confirmar">Confirmar senha</label><div class="input-wrap"><span>♙</span><input id="confirmar" name="confirmar" type="password" autocomplete="new-password" placeholder="Digite a senha novamente" required minlength="8"><button class="toggle-password" type="button" data-toggle="confirmar">◎</button></div>
<div class="notice" id="feedback" role="alert"></div><button class="submit" type="submit"><span>Criar conta</span><b>→</b></button></form><div class="auth-bottom">Já possui uma conta? <a href="login.php">Entrar</a></div></section></main></body></html>
